#include "daxa_refinement_common.hpp"
using namespace refinement_app;
int main(int argc,char** argv){try{
    if(argc==2&&std::string(argv[1])=="--shader-directory"){std::cout<<DaxaRefinement::shader_directory()<<'\n';return 0;}
    Options options(argc,argv);Prepared prepared(options);auto frames=options.number_or("--frames",100),warmup=options.number_or("--warmup",20);check(frames>=1&&frames<=300&&warmup<=30,"frames1..300/warmup0..30 required");auto variant=options.values.contains("--variant")?options.values.at("--variant"):"coarse_refine";check(variant=="coarse_alone"||variant=="coarse_refine","unknown benchmark variant");bool enabled=variant=="coarse_refine";auto context=std::make_shared<DaxaFoundation>(options.validation);auto depth=std::make_unique<DaxaDepthPipeline>(prepared.coarse.rectification,prepared.depth,context,prepared.source);auto initial=depth->enqueue(prepared.source);initial.wait();auto stage=std::make_unique<DaxaRefinement>(context,prepared.target.rectification,initial,prepared.refinement);initial={};depth->drain();
    constexpr unsigned count=20;std::array<std::vector<double>,count> samples;for(auto& v:samples)v.resize(frames);DaxaDepthPipeline::Frame coarse;DaxaRefinement::Frame output;
    for(unsigned i=0;i<frames+warmup;++i){auto a=Clock::now();output={};stage->collect();coarse={};check(stage->can_process(),"refinement admission before upload failed");coarse=depth->enqueue(prepared.source);if(enabled)output=stage->process(coarse);auto b=Clock::now();if(enabled)output.wait();else coarse.wait();auto c=Clock::now();auto dt=coarse.timings();DaxaRefinementTiming rt;if(enabled)rt=output.timings();auto d=Clock::now();auto mask=dt.preprocessing.timestamp_bits==64?UINT64_MAX:(uint64_t(1)<<dt.preprocessing.timestamp_bits)-1;double combined=enabled?double((rt.end_tick-dt.preprocessing.start_tick)&mask)*dt.preprocessing.timestamp_period/1e6:dt.combined_gpu_ms;
        if(i>=warmup){std::array<double,count> values{std::chrono::duration<double,std::milli>(b-a).count(),std::chrono::duration<double,std::milli>(c-b).count(),std::chrono::duration<double,std::milli>(d-c).count(),std::chrono::duration<double,std::milli>(d-a).count(),depth->last_upload_cpu_ms(),dt.preprocessing.upload_ms,dt.preprocessing.decode_ms,dt.preprocessing.rectify_ms,dt.left.total_gpu_ms,dt.right.total_gpu_ms,dt.lr_gpu_ms,dt.metric_metadata_gpu_ms,dt.combined_gpu_ms,rt.stage_gpu_ms[0],rt.stage_gpu_ms[1],rt.stage_gpu_ms[2],rt.stage_gpu_ms[3],rt.stage_gpu_ms[4],rt.total_gpu_ms,combined};for(unsigned k=0;k<count;++k)samples[k][i-warmup]=values[k];}}
    auto result=prepared.report();result["variant"]=variant;result["frames"]=frames;result["warmup"]=warmup;result["slots"]=prepared.refinement.slots;result["validation_requested"]=options.validation;result["device"]=json::parse(context->report());result["requested_refinement_buffer_bytes"]=stage->requested_buffer_bytes();result["requested_combined_buffer_bytes"]=depth->requested_combined_buffer_bytes()+stage->requested_buffer_bytes();result["active_requested_buffer_bytes"]=depth->requested_combined_buffer_bytes()+(enabled?stage->requested_buffer_bytes():0);result["memory_scope"]="requested buffer bytes only; excludes driver allocator queries CPU diagnostic/source; refinement setup allocated even for coarse-alone control";result["combined_scope"]="same shared queue coarse upload start through final metric end; direct timestamp difference including gaps";
    if(enabled){auto diagnostic_begin=Clock::now();auto r=stage->readback(output);result["actual_candidate_evaluations"]=std::accumulate(r.evaluated_candidates.begin(),r.evaluated_candidates.end(),uint64_t{});result["metric_valid_pixels"]=std::accumulate(r.metric_validity.begin(),r.metric_validity.end(),uint64_t{});result["guided_pixels"]=std::count(r.method.begin(),r.method.end(),1u);result["subpixel_applied_pixels"]=std::accumulate(r.subpixel_applied.begin(),r.subpixel_applied.end(),uint64_t{});if(options.values.contains("--dump-prefix"))result["files"]=dump(r,options.values.at("--dump-prefix"));result["diagnostic_after_timing_ms"]=std::chrono::duration<double,std::milli>(Clock::now()-diagnostic_begin).count();}
    constexpr const char* keys[]{"enqueue_cpu_ms","wait_cpu_ms","query_cpu_ms","host_wall_ms","upload_cpu_ms","gpu_upload_ms","gpu_decode_ms","gpu_coarse_rectify_ms","gpu_left_sgm_ms","gpu_right_sgm_ms","gpu_coarse_lr_ms","gpu_coarse_metric_ms","gpu_coarse_queue_span_ms","gpu_target_rectify_ms","gpu_census_ms","gpu_guided_match_ms","gpu_refined_lr_ms","gpu_refined_metric_ms","gpu_refinement_queue_span_ms","gpu_combined_queue_span_ms"};for(unsigned k=0;k<count;++k){result[keys[k]]=summary(samples[k]);result["raw_samples_ms"][keys[k]]=samples[k];}
    output={};stage->collect();result["refinement_source_retirements"]=stage->completed_source_retirements();stage.reset();coarse={};depth->drain();result["coarse_output_retirements"]=depth->completed_output_retirements();depth.reset();context->close();check(!context->validation_errors&&!context->validation_warnings,"refinement benchmark validation failed through teardown");result["validation_errors_after_teardown"]=context->validation_errors.load();result["validation_warnings_after_teardown"]=context->validation_warnings.load();prepared.verify(options);auto bytes=result.dump(2)+'\n';write(options.values.at("--output"),bytes.data(),bytes.size());return 0;
}catch(std::exception const& e){std::cerr<<"daxa_refinement_benchmark: "<<e.what()<<'\n';return 1;}}
